// Coffee mug — replicad/BREP showcase: cylinder body with a cut cavity, a
// torus-loop handle standing out from the wall, and coffee filling the cavity.
// Colours (white ceramic, blue rim band, brown coffee) are applied as
// coordinate paint regions on the baked entry, so the code stays pure geometry.
const { BREP } = api;

// Body: 50 mm dia (r 25), 70 mm tall, floor on z=0, 2.5 mm walls, open top.
// The 6 mm rim band stands 0.4 mm proud (r 25.4, z 64..70) so the surface has a
// real edge at z=64 for the blue band paint to follow — a crisp colour boundary.
const body = BREP.cylinder(25, 65).fuse(BREP.cylinder(25.4, 6).translate([0, 0, 64]));

// Handle: a torus (major 13, minor 3.5) stood up so its ring lies in the XZ
// plane, centred 34 mm out and at mid-height. Its outer edge reaches x=50.5
// (25.5 mm clear of the wall) around an 18.5 mm clear finger gap (wall at x=25
// to the loop's inner edge at x=43.5). The inner half of
// the ring is buried in the wall and trimmed back by the cavity cut below,
// so only the graspable loop shows.
const handle = BREP.torus(13, 3.5).rotate(90, [1, 0, 0]).translate([34, 0, 35]);

const solid = body.fuse(handle);

// Cavity: r 22.5 from the 2.5 mm floor up through the open rim. Cutting after
// the handle fuse keeps the handle out of the cavity.
const mug = solid.cut(BREP.cylinder(22.5, 70).translate([0, 0, 2.5]));

// Coffee: fills the cavity from the floor up to z=55. Radius 23 bites 0.5 mm
// into the inner wall and the base starts at z=2 (inside the floor), so the
// coffee is fused to the mug — ONE solid, nothing floating.
const coffee = BREP.cylinder(23, 53).translate([0, 0, 2]);

return mug.fuse(coffee);

